12	/** Typst strings are not JSON strings: control characters use \u{...}. */
13	export { typstString } from "./string";
14	import { typstString } from "./string";
15	
16	const text = (value: string) => (value ? `#text(${typstString(value)})` : "");
17	const number = (
18	  raw: string | null | undefined,
19	  fallback: number,
20	  min: number,
21	  max: number,
22	) => {
23	  if (raw == null || raw.trim() === "") return fallback;
24	  const n = Number(raw);
25	  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback;
26	};
27	
28	function color(raw: string): string | null {
29	  if (/^#[\da-f]{3}(?:[\da-f]{3})?$/i.test(raw))
30	    return `rgb(${typstString(raw)})`;
31	  const rgb =
32	    /^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)(?:\s*,\s*([\d.]+))?\s*\)$/i.exec(
33	      raw,
34	    );
35	  if (!rgb) return null;
36	  const channels = rgb.slice(1, 4).map((n) => Math.min(255, Number(n)));
37	  if (rgb[4] != null)
38	    channels.push(Math.round(Math.min(1, Number(rgb[4])) * 255));
39	  return `rgb(${channels.join(", ")})`;
40	}
