42	/** Never interpolate manuscript text as executable Typst markup. */
43	export function serializeTypst(payload: ExportPayload): TypstDocument {
44	  const dom = new DOMParser().parseFromString(payload.html, "text/html");
45	  const assets: TypstDocument["assets"] = [];
46	  const endnotes: string[] = [];
47	  const children = (element: Node): string =>
48	    Array.from(element.childNodes).map(visit).join("");
49	
50	  function inlineStyle(el: HTMLElement, body: string): string {
51	    const args: string[] = [];
52	    if (el.style.fontFamily)
53	      args.push(
54	        `font: ${typstString(el.style.fontFamily.includes("monospace") ? "DejaVu Sans Mono" : el.style.fontFamily.split(",")[0].replace(/['"]/g, "").trim())}`,
55	      );
56	    const fill = color(el.style.color);
57	    if (fill) args.push(`fill: ${fill}`);
58	    const size = /^(\d+(?:\.\d+)?)(px|pt|rem|em)$/.exec(el.style.fontSize);
59	    if (size) {
60	      const n = Math.min(200, Math.max(1, Number(size[1])));
61	      args.push(
62	        `size: ${size[2] === "px" ? n * 0.75 + "pt" : size[2] === "rem" ? n * 12 + "pt" : n + size[2]}`,
63	      );
64	    }
65	    if (el.style.fontWeight === "bold" || Number(el.style.fontWeight) >= 600)
66	      args.push('weight: "bold"');
67	    if (el.style.fontStyle === "italic") args.push('style: "italic"');
68	    if (args.length) body = `#text(${args.join(", ")})[${body}]`;
69	    const fillBackground = color(el.style.backgroundColor);
70	    if (fillBackground) body = `#highlight(fill: ${fillBackground})[${body}]`;
71	    return body;
72	  }
73	
74	  function paragraph(el: HTMLElement, body: string): string {
75	    if (el.tagName === "P" && el.parentElement === dom.body && body) {
76	      body = `#twyne-opening[${body}]`;
77	    }
78	    const align = el.style.textAlign;
79	    const settings: string[] = [];
80	    if (align === "justify") settings.push("#set par(justify: true)");
81	    else if (["left", "center", "right"].includes(align))
82	      settings.push("#set par(justify: false)");
83	    const leading = el.style.lineHeight;
84	    if (/^[\d.]+$/.test(leading)) {
85	      settings.push(
86	        `#set par(leading: ${Math.max(0, number(leading, 1.5, 1, 3) - 1)}em)`,
87	      );
88	    }
89	    if (settings.length) body = `${settings.join("\n")}\n${body}`;
90	    if (["left", "center", "right"].includes(align))
91	      body = `#align(${align})[${body}]`;
92	    const indent = number(el.getAttribute("data-indent"), 0, 0, 8);
93	    if (indent) body = `#pad(left: ${indent * 18}pt)[${body}]`;
94	    const options: string[] = [];
95	    // Keep the following paragraph's automatic above-space from overriding
96	    // an author's explicit space-after (including zero).
97	    if (el.tagName === "P" && el.parentElement === dom.body) {
98	      if (!el.hasAttribute("data-space-before")) options.push("above: 0pt");
99	      if (!el.hasAttribute("data-space-after")) options.push("below: 16.2pt");
100	    }
101	    for (const [attr, key] of [
102	      ["data-space-before", "above"],
103	      ["data-space-after", "below"],
104	    ]) {
105	      if (el.hasAttribute(attr))
106	        options.push(`${key}: ${number(el.getAttribute(attr), 0, 0, 144)}pt`);
107	    }
108	    if (el.getAttribute("data-keep-with-next") === "true")
109	      options.push("sticky: true");
110	    return `#block(${options.join(", ")})[${body || "#v(1em)"}]\n`;
111	  }
112	
113	  function table(el: HTMLTableElement): string {
114	    const rows = Array.from(el.rows);
115	    if (!rows.length) return "";
116	    // Explicit coordinates keep merged cells from shifting subsequent rows.
117	    const occupied: boolean[][] = [];
118	    const cells: string[] = [];
119	    let columns = 1;
120	    rows.forEach((row, y) => {
121	      occupied[y] ??= [];
122	      let x = 0;
123	      for (const cell of Array.from(row.cells)) {
124	        while (occupied[y][x]) x++;
125	        const colspan = Math.round(
126	          number(cell.getAttribute("colspan"), 1, 1, 100),
127	        );
128	        const rowspan = Math.min(
129	          rows.length - y,
130	          Math.round(number(cell.getAttribute("rowspan"), 1, 1, 100)),
131	        );
132	        const options = [
133	          `x: ${x}`,
134	          `y: ${y}`,
135	          `colspan: ${colspan}`,
136	          `rowspan: ${rowspan}`,
137	        ];
138	        const fill = color(
139	          cell.getAttribute("data-cell-background") ||
140	            cell.style.backgroundColor,
141	        );
142	        if (fill) options.push(`fill: ${fill}`);
143	        else if (cell.tagName === "TH") options.push('fill: rgb("#ebe1c9")');
144	        const align =
145	          cell.getAttribute("data-cell-horizontal-alignment") ||
146	          cell.style.textAlign;
147	        if (["left", "center", "right"].includes(align))
148	          options.push(`align: ${align}`);
149	        let body = children(cell);
150	        if (cell.tagName === "TH") body = `#strong[${body}]`;
151	        cells.push(`table.cell(${options.join(", ")})[${body}]`);
152	        for (let yy = y; yy < y + rowspan; yy++) {
153	          occupied[yy] ??= [];
154	          for (let xx = x; xx < x + colspan; xx++) occupied[yy][xx] = true;
155	        }
156	        x += colspan;
157	        columns = Math.max(columns, x);
158	      }
159	    });
160	    const caption =
161	      el.caption?.textContent || el.getAttribute("data-table-caption");
162	    const body = `#table(columns: ${columns},\n${cells.join(",\n")},\n)`;
163	    return (
164	      body + (caption ? `\n#align(center)[#emph[${text(caption)}]]` : "") + "\n"
165	    );
166	  }
167	
168	  function visit(node: Node): string {
169	    if (node.nodeType === 3)
170	      return text((node.textContent ?? "").replace(/[\t\n\r ]+/g, " "));
171	    if (node.nodeType !== 1) return "";
172	    const el = node as HTMLElement;
173	    const tag = el.tagName.toLowerCase();
174	    if (
175	      ["script", "style", "template", "input", "button", "label"].includes(tag)
176	    )
177	      return "";
178	    const kind = el.getAttribute("data-type");
179	    if (kind === "page-break" || el.hasAttribute("data-page-break"))
180	      return "#pagebreak()\n";
181	    if (kind === "inline-math" || kind === "block-math")
182	      return `#twyne-math(${typstString(el.getAttribute("data-latex") ?? el.textContent ?? "")}, block: ${kind === "block-math"})`;
183	    if (kind === "mermaid-diagram")
184	      return `#twyne-mermaid(${typstString(el.getAttribute("data-mermaid-source") ?? el.textContent ?? "")})`;
185	    if (kind === "footnote")
186	      return `#footnote[${text(el.getAttribute("data-endnote-text") ?? "")}]`;
187	    if (kind === "endnote") {
188	      endnotes.push(el.getAttribute("data-endnote-text") ?? "");
189	      return `#super[${text(String(endnotes.length))}]`;
190	    }
191	    if (tag === "img") {
192	      const url = el.getAttribute("src");
193	      if (!url)
194	        throw new Error(
195	          "An image has no saved source. Finish uploading it before exporting.",
196	        );
197	      const path =
198	        assets.find((asset) => asset.url === url)?.path ??
199	        `/images/image-${assets.length + 1}`;
200	      if (!assets.some((asset) => asset.path === path))
201	        assets.push({ path, url });
202	      const figure = el.closest("figure");
203	      const width = number(
204	        figure?.getAttribute("data-image-width"),
205	        100,
206	        10,
207	        100,
208	      );
209	      return `#image(${typstString(path)}, width: ${width}%, alt: ${typstString(el.getAttribute("alt") ?? "")})`;
210	    }
211	    if (tag === "table") return table(el as HTMLTableElement);
212	    if (tag === "pre")
213	      return `#raw(${typstString(el.textContent ?? "")}, block: true)\n`;
214	    if (tag === "code") return `#raw(${typstString(el.textContent ?? "")})`;
215	    if (tag === "br") return "#linebreak()";
216	    if (tag === "hr") return "#line(length: 100%)\n";
217	    if (tag === "ul" || tag === "ol") {
218	      const items = Array.from(el.children)
219	        .filter((c) => c.tagName === "LI")
220	        .map((li) => {
221	          const checkbox =
222	            li.getAttribute("data-type") === "taskItem"
223	              ? text(
224	                  li.getAttribute("data-checked") === "true" ? "[x] " : "[ ] ",
225	                )
226	              : "";
227	          return `[${checkbox}${children(li)}]`;
228	        });
229	      if (!items.length) return "";
230	      const start =
231	        tag === "ol"
232	          ? `start: ${Math.round(number(el.getAttribute("start"), 1, 1, 1000000))}, `
233	          : "";
234	      return `#${tag === "ol" ? "enum" : "list"}(${start}${items.join(",\n")})\n`;
235	    }
236	    const body = inlineStyle(el, children(el));
237	    if (/^h[1-6]$/.test(tag))
238	      return paragraph(el, `#heading(level: ${tag[1]})[${body}]`);
239	    if (tag === "p") return paragraph(el, body);
240	    if (tag === "blockquote") return `#quote(block: true)[${body}]\n`;
241	    const marks: Record<string, string> = {
242	      strong: "strong",
243	      b: "strong",
244	      em: "emph",
245	      i: "emph",
246	      u: "underline",
247	      s: "strike",
248	      del: "strike",
249	      strike: "strike",
250	      sup: "super",
251	      sub: "sub",
252	    };
253	    if (marks[tag]) return `#${marks[tag]}[${body}]`;
254	    if (tag === "mark") {
255	      const fill =
256	        color(el.getAttribute("data-color") || el.style.backgroundColor) ??
257	        'rgb("#fff0a6")';
258	      return `#highlight(fill: ${fill})[${body}]`;
259	    }
260	    if (tag === "a") {
261	      const href = el.getAttribute("href") ?? "";
262	      if (/^(https?:\/\/|mailto:|tel:)/i.test(href))
263	        return `#link(${typstString(href)})[${body}]`;
264	      return body;
265	    }
266	    if (tag === "figure") {
267	      const align = el.getAttribute("data-image-align") || "center";
268	      return `#block[#align(${["left", "right", "center"].includes(align) ? align : "center"})[${body}]]\n`;
269	    }
270	    if (tag === "figcaption") return `\n#block[#emph[${body}]]\n`;
271	    if (["div", "section", "article"].includes(tag)) return `#block[${body}]\n`;
272	    // Editor annotations are transparent wrappers; their private attributes never leave the draft.
273	    if (["span", "li", "small", "abbr"].includes(tag)) return body;
274	    throw new Error(
275	      `Typst export does not yet support <${tag}> content. Use PDF… for this folio.`,
276	    );
277	  }
278	
279	  const body = children(dom.body);
280	  const notes = [
281	    ...endnotes,
282	    ...(payload.marginalia ?? []).map(
283	      (m) =>
284	        `${m.personaName || "Editor"}: ${m.anchor ? `“${m.anchor}” — ` : ""}${m.feedback}`,
285	    ),
286	  ];
287	  const bibliography = (payload.bibliography ?? [])
288	    .filter((b) => b.url || b.doi || b.title)
289	    .map((b) => formatCitation(b, payload.citationStyle ?? "mla"));
290	  const section = (title: string, entries: string[]) =>
291	    entries.length
292	      ? `\n#heading(level: 2)[${text(title)}]\n#enum(${entries.map((entry) => `[${text(entry)}]`).join(",\n")})\n`
293	      : "";
294	  const title =
295	    dom.body.firstElementChild?.tagName === "H1"
296	      ? ""
297	      : `#heading(level: 1)[${text(payload.title)}]\n`;
298	  return {
299	    source: [
300	      "// Exported from Twyne. Editing this file does not change your saved folio.",
301	      typstPageSetup(payload),
302	      title +
303	        body +
304	        section("Notes", notes) +
305	        section("Bibliography", bibliography),
306	    ].join("\n\n"),
307	    assets: [...assets, ...typstDecorations(payload).assets],
308	  };
309	}
