205	export function typstPageSetup(
206	  payload: ExportPayload,
207	  source?: string,
208	): string {
209	  const layout = payload.layout ?? DEFAULT_LAYOUT;
210	  const page = resolvePageSetup(layout);
211	  const decoration = typstDecorations(payload, source);
212	  const size = { small: 40.5, medium: 56.7, large: 74.25 }[
213	    decoration.settings.size
214	  ];
215	  const initialStyles = [
216	    `#let twyne-initial-mode = ${typstString(decoration.settings.mode)}`,
217	    `#let twyne-initial-size = ${size}pt`,
218	    `#let twyne-initial-letter = ${decoration.initial ? typstString(decoration.initial.glyph) : "none"}`,
219	    `#let twyne-initial-artwork(glyph, size) = ${decoration.initial ? `image(${typstString(decoration.initial.path)}, width: size, height: size, alt: glyph)` : "text(glyph)"}`,
220	  ].join("\n");
221	  const frameWidth = page.widthIn * 72 - 36;
222	  const frameHeight = page.heightIn * 72 - 36;
223	  const middleWidth = frameWidth - 72;
224	  const middleHeight = frameHeight - 72;
225	  const frameImage = (part: string, width: number, height: number) =>
226	    `image(${typstString(decoration.frame!.slices[part].path)}, width: ${width}pt, height: ${height}pt, fit: "stretch", alt: none)`;
227	  const tileCounts = pageBorderTileCounts(layout);
228	  const frameEdge = (part: string, horizontal: boolean) => {
229	    const count = horizontal ? tileCounts.horizontal : tileCounts.vertical;
230	    const width = horizontal ? middleWidth / count : 36;
231	    const height = horizontal ? 36 : middleHeight / count;
232	    return `stack(dir: ${horizontal ? "ltr" : "ttb"}, spacing: 0pt, ${Array.from({ length: count }, () => frameImage(part, width, height)).join(", ")})`;
233	  };
234	  const frameStyles = decoration.frame
235	    ? `
236	#let twyne-page-frame = box(width: ${frameWidth}pt, height: ${frameHeight}pt,
237	  grid(columns: (36pt, ${middleWidth}pt, 36pt), rows: (36pt, ${middleHeight}pt, 36pt), gutter: 0pt,
238	    ${frameImage("nw", 36, 36)}, ${frameEdge("n", true)}, ${frameImage("ne", 36, 36)},
239	    ${frameEdge("w", false)}, [], ${frameEdge("e", false)},
240	    ${frameImage("sw", 36, 36)}, ${frameEdge("s", true)}, ${frameImage("se", 36, 36)}))
241	`.trim()
242	    : "";
243	  const background = decoration.frame
244	    ? "align(center + horizon, twyne-page-frame)"
245	    : decoration.border === "none"
246	      ? "none"
247	      : 'align(center + horizon, rect(width: 100% - 36pt, height: 100% - 36pt, stroke: 0.6pt + rgb("#cabb9d")))';
248	  const margin = Object.entries(resolveMargins(layout))
249	    .map(
250	      ([key, value]) =>
251	        // The editor's small screen gutters are not enough for a framed page.
252	        // Reserve room for the frame and running furniture; larger chosen
253	        // margins still apply unchanged.
254	        `${key}: ${Math.max(decoration.frame ? 60 : key === "top" || key === "bottom" ? 54 : 36, Math.min(8, Math.max(0, Number.isFinite(value) ? value : 0)) * 12)}pt`,
255	    )
256	    .join(", ");
257	  const header = payload.header || (layout.runningHeader ? payload.title : "");
258	  // Clear the frame behind running furniture, like labels printed into a rule.
259	  const furniture = (body: string) =>
260	    `#box(fill: rgb("#fbf6e7"), inset: (x: 3pt))[${body}]`;
261	  const footer = [
262	    payload.footer ? furniture(`#text(${typstString(payload.footer)})`) : "",
263	    layout.pageNumbers
264	      ? `#h(1fr)${furniture('#context counter(page).display("1")')}`
265	      : "",
266	  ]
267	    .filter(Boolean)
268	    .join(" ");
269	  return [
270	    `#set document(title: ${typstString(payload.title)})`,
271	    initialStyles,
272	    TYPST_EDITORIAL_STYLES,
273	    frameStyles,
274	    `#set columns(gutter: ${resolveColumnGap(layout) * 12}pt)`,
275	    `#set page(width: ${page.widthIn}in, height: ${page.heightIn}in, columns: ${resolveColumns(layout)}, margin: (${margin}), fill: rgb("#fbf6e7"), background: ${background}, header-ascent: 20%, footer-descent: 20%, header: [${header ? `#set text(font: "Special Elite", size: 8pt, fill: rgb("#4a3f33"))\n#set par(justify: false)\n${furniture(`#text(${typstString(header)})`)}` : ""}], footer: [${footer ? `#set text(font: "Special Elite", size: 8pt, fill: rgb("#4a3f33"))\n#set par(justify: false)\n${footer}` : ""}])`,
276	  ].join("\n\n");
277	}
