149	      ([k, v]) =>
150	        /^[a-zA-Z][\w:.-]*$/.test(k) &&
151	        !/^on/i.test(k) &&
152	        typeof v === "string" &&
153	        (!/^(href|src)$/i.test(k) || !/^\s*(javascript|vbscript):/i.test(v)),
