167	/** Each wrapper preserves only structure/attributes. All text lives in its editable body. */
168	export function htmlToTypst(html: string): string {
169	  bounded(html);
170	  const dom = new DOMParser().parseFromString(html, "text/html");
171	  function visit(node: Node, depth = 0): string {
172	    if (depth > MAX_DEPTH)
173	      throw new Error("Typst document nesting exceeds the editing limit.");
174	    if (node.nodeType === 3)
175	      return node.textContent ? `#text(${typstString(node.textContent)})` : "";
176	    if (node.nodeType !== 1) return "";
177	    const el = node as HTMLElement;
178	    if (el.hasAttribute("data-typst-source"))
179	      return el.getAttribute("data-typst-source") ?? "";
180	    const tag = el.tagName.toLowerCase();
181	    if (!allowedTags.has(tag)) return "";
182	    const attrs = Object.fromEntries(
183	      Array.from(el.attributes).map((a) => [a.name, a.value]),
184	    );
185	    if (tag === "table") {
186	      const firstRow = el.querySelector("tr");
187	      const widths = firstRow
188	        ? Array.from(firstRow.children).flatMap((cell) => {
189	            const span = Math.max(1, Number(cell.getAttribute("colspan")) || 1);
190	            const raw = (cell.getAttribute("colwidth") ?? "").split(",");
191	            return Array.from({ length: span }, (_, i) =>
192	              Math.max(0, Number(raw[i]) || 0),
193	            );
194	          })
195	        : [];
196	      if (widths.some(Boolean))
197	        attrs["data-twyne-column-widths"] = widths.join(",");
198	      const row = el.querySelector("tr");
199	      if (el.querySelector("caption"))
200	        attrs["data-twyne-caption"] =
201	          el.querySelector("caption")?.textContent ?? "";
202	      attrs["data-twyne-columns"] = String(
203	        row
204	          ? Array.from(row.children).reduce(
205	              (n, cell) =>
206	                n + Math.max(1, Number(cell.getAttribute("colspan")) || 1),
207	              0,
208	            )
209	          : 1,
210	      );
211	    }
212	    let body = Array.from(el.childNodes)
213	      .map((n) => visit(n, depth + 1))
214	      .join("");
215	    if (tag === "img")
216	      body = `#twyne-image(${typstString(el.getAttribute("src") ?? "")}, width: 100%, alt: ${typstString(el.getAttribute("alt") ?? "")})`;
217	    if (el.hasAttribute("data-latex"))
218	      body = `#twyne-math(${typstString(el.getAttribute("data-latex") ?? "")}, block: ${el.getAttribute("data-type") === "block-math"})`;
219	    if (el.getAttribute("data-type") === "mermaid-diagram")
220	      body = `#twyne-mermaid(${typstString(el.getAttribute("data-mermaid-source") ?? "")})`;
221	    return `#twyne-node(${typstString(tag)}, ${typstString(JSON.stringify(attrs))})[${body}]`;
222	  }
223	  return (
224	    TYPST_DOCUMENT_PREAMBLE +
225	    Array.from(dom.body.childNodes)
226	      .map((n) => visit(n))
227	      .join("\n\n")
228	  );
229	}
