231	// String and bracket scanning deliberately does not execute code, import packages or fetch URLs.
232	function quoted(source: string, start: number): { value: string; end: number } {
233	  if (source[start] !== '"') throw new Error("Expected a string");
234	  let value = "";
235	  for (let i = start + 1; i < source.length; i++) {
236	    const c = source[i];
237	    if (c === '"') return { value, end: i + 1 };
238	    if (c !== "\\") {
239	      value += c;
240	      continue;
241	    }
242	    const next = source[++i];
243	    if (next === "u" && source[i + 1] === "{") {
244	      const end = source.indexOf("}", i + 2);
245	      const hex = source.slice(i + 2, end);
