/** Read both the manuscript and its local revision stamp for sync conflicts. */
export async function loadFolioContentSnapshotFromIdb(
  folioId: string,
): Promise<FolioContentSnapshot | null> {
  if (!isBrowser()) return null;
  try {
    return await tx("folio-content", "readwrite", async (t) => {
      const store = t.objectStore("folio-content");
      const rec = await reqAsPromise<FolioContentSnapshot | undefined>(
        store.get(folioId),
      );
      if (!rec) return null;
      if (rec.typstSource === undefined) {
        rec.typstSource = htmlToTypst(rec.html);
        rec.format = "typst";
        await reqAsPromise(store.put(rec));
      }
      return rec;
    });
  } catch {
    return null;
  }
}

export const FOLIO_CONTENT_SAVED = "twyne:folio-content-saved";
export interface FolioContentSavedDetail extends FolioContentSnapshot {
  origin: "local" | "remote";
}

async function updateFolioContent(
  folioId: string,
  update: (previous: FolioContentSnapshot | undefined) => FolioContentSnapshot,
  origin: FolioContentSavedDetail["origin"] = "local",
): Promise<FolioContentSnapshot | undefined> {
  if (!isBrowser()) return;
  const rec = await tx("folio-content", "readwrite", async (t) => {
    const store = t.objectStore("folio-content");
    const previous = await reqAsPromise<FolioContentSnapshot | undefined>(
      store.get(folioId),
    );
    const next = update(previous);
    await reqAsPromise(store.put(next));
    return next;
  });
  // A remote restoration may carry a historical timestamp. Invalidate its
  // obsolete emergency copy explicitly instead of relying on wall clocks.
  if (origin === "remote") clearCrashMirror(folioId);
  window.dispatchEvent(
    new CustomEvent<FolioContentSavedDetail>(FOLIO_CONTENT_SAVED, {
      detail: { ...rec, origin },
    }),
  );
  return rec;
}

export async function saveFolioContentToIdb(
  folioId: string,
  html: string,
): Promise<void> {
  // Stamp when the snapshot is queued, not when an asynchronous read finishes.
  // An older in-flight save must not look newer than a departure mirror.
  const updatedAt = Date.now();
  await updateFolioContent(folioId, (previous) => ({
    folioId,
    html,
    format: "typst",
    typstSource:
      previous?.typstSource !== undefined
        ? previous.html === html
          ? previous.typstSource
          : reconcileTypstSource(previous.typstSource, html)
        : htmlToTypst(html),
    updatedAt: previous?.html === html ? previous.updatedAt : updatedAt,
  }));
}

/** Recover under the same transaction that checks the canonical revision. */
export async function recoverFolioContentFromCrashMirror(
  folioId: string,
): Promise<boolean> {
  if (!isBrowser() || readCrashMirror(folioId) === null) return false;
  const result = await tx("folio-content", "readwrite", async (t) => {
    const store = t.objectStore("folio-content");
    const previous = await reqAsPromise<FolioContentSnapshot | undefined>(
      store.get(folioId),
    );
    const html = readCrashMirror(folioId, previous);
    if (html === null) return null;
    if (previous?.html === html)
      return { html, recovered: false, snapshot: previous };
    const snapshot: FolioContentSnapshot = {
      folioId,
      html,
      format: "typst",
      typstSource:
        previous?.typstSource !== undefined
          ? reconcileTypstSource(previous.typstSource, html)
          : htmlToTypst(html),
      updatedAt: Date.now(),
    };
    await reqAsPromise(store.put(snapshot));
    return { html, recovered: true, snapshot };
  });
  if (!result) return false;
  clearCrashMirror(folioId, result.html);
  if (result.recovered)
    window.dispatchEvent(
      new CustomEvent<FolioContentSavedDetail>(FOLIO_CONTENT_SAVED, {
        detail: { ...result.snapshot, origin: "local" },
      }),
    );
  return result.recovered;
}

/** Save source and its visual projection as one recoverable document. */
export async function saveFolioTypstToIdb(
  folioId: string,
  source: string,
  html?: string,
  expectedSource?: string | null,
  origin: FolioContentSavedDetail["origin"] = "local",
): Promise<void> {
  await updateFolioContent(
    folioId,
    (previous) => {
      if (
        expectedSource !== undefined &&
        (previous?.typstSource ?? null) !== expectedSource
      )
        throw new Error(
          "The manuscript changed while this source was being edited. Review the latest source before applying.",
        );
      return {
        folioId,
        html: html ?? typstToHtml(source),
        format: "typst",
        typstSource: source,
        updatedAt:
          previous?.typstSource === source ? previous.updatedAt : Date.now(),
      };
    },
    origin,
  );
  // An explicitly applied source supersedes the pending visual fallback.
  clearCrashMirror(folioId);
}

