    for (const source of [
      '#twyne-scene-break(style: "confetti")',
      "#twyne-subtitle(weird: 1)[Words]",
      "#twyne-epigraph(attribution: [*Ovid*])[Quote]",
      "#twyne-kicker[Unclosed",
    ]) {
      const html = typstToHtml(source);
      expect(html).toContain("raw-typst");
    }
  });

